/*
The VL53L0X breakout module communicates via the I²C 
protocol and typically includes an onboard 2.8V 
regulator and level shifter to support 3V to 5V logic.
 For an standard Arduino Uno:
 VIN / VCC → Arduino 5V
 GND → Arduino GND
 SCL → Arduino A5 (SCL)
 SDA → Arduino A4 (SDA)
*/

#include "Adafruit_VL53L0X.h"

Adafruit_VL53L0X lox = Adafruit_VL53L0X();

void setup() {
  Serial.begin(115200);
  while (!Serial) { delay(1); }
  
  Serial.println("Adafruit VL53L0X test");
  if (!lox.begin()) {
    Serial.println(F("Failed to boot VL53L0X"));
    while(1);
  }
  Serial.println(F("VL53L0X booted!"));
}

void loop() {
  VL53L0X_RangingMeasurementData_t measure;
  
  lox.rangingTest(&measure, false); // pass in 'true' for debug data printout

  if (measure.RangeStatus != 4) {  // phase failures have incorrect data
    Serial.print("Distance (mm): ");
    Serial.println(measure.RangeMilliMeter);
  } else {
    Serial.println("Out of range ");
  }
  
  delay(100);
}
